class Solution {
public:
    vector<string> getFolderNames(vector<string>& names) {
        unordered_map<string, int> cnt;
        vector<string> ans;
        ans.reserve(names.size());
        for (const string& s : names) {
            auto it = cnt.find(s);
            if (it == cnt.end()) {
                ans.push_back(s);
                cnt[s] = 1;
            } else {
                int k = it->second;
                string candidate = s + "(" + to_string(k) + ")";
                while (cnt.find(candidate) != cnt.end()) {
                    k++;
                    candidate = s + "(" + to_string(k) + ")";
                }
                ans.push_back(candidate);
                cnt[candidate] = 1;
                cnt[s] = k + 1;
            }
        }
        return ans;
    }
};
